window.AUTH=window.AUTH||{};window.AUTH["21-439"]={"d":"21-439","id":"2021/21-439","n":"Nance v. Ward","briefs":[{"k":"petitioner","label":"Brief of petitioner Michael Nance","date":"2022-02-25","url":"https://www.supremecourt.gov/DocketPDF/21/21-439/215058/20220225153529813_21-439%20ts.pdf","side":"pet","n":30},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2022-03-04","url":"https://www.supremecourt.gov/DocketPDF/21/21-439/217783/20220304183641295_21-439tsacUnitedStates%20Final.pdf","side":"us","n":51},{"k":"respondent","label":"Brief of respondents Ward, Commissioner, Georgia Department of Corrections, et al.","date":"2022-03-28","url":"https://www.supremecourt.gov/DocketPDF/21/21-439/219614/20220328165350628_21%20439%20Resp.%20Br..pdf","side":"res","n":70},{"k":"reply","label":"Reply of petitioner Michael Nance","date":"2022-04-15","url":"https://www.supremecourt.gov/DocketPDF/21/21-439/221105/20220415110506029_21-439%20rb.pdf","side":"pet","n":23}],"opinion":"https://www.supremecourt.gov/opinions/21pdf/597us1r56_p86b.pdf","tr":true,"items":[{"t":"case","label":"Banister v. Davis","cite":"140 S. Ct. 1698","y":2020,"id":"2019/18-6943","sc":1,"ar":2,"sum":"The Court held that a timely Rule 59(e) motion to “amend or alter” a habeas court’s judgment is not a second or successive habeas petition.","sumSrc":"Oyez","by":{"0":"22, 41, 42, 44, 45","2":"passim","3":"20, 21"}},{"t":"case","label":"Baze v. Rees","cite":"553 U.S. 35","y":2008,"id":"2007/07-5439","sc":1,"sum":"The Court held that Kentucky's lethal injection scheme did not violate the Eighth Amendment. Noting that the inmates had conceded the \"humane nature\" of the procedure when performed correctly, the divided Court inmates had failed to prove that incorrect administration of the drugs would amount to cruel and unusual punishment.","sumSrc":"Oyez","by":{"0":"9, 11","1":"14","2":"passim"}},{"t":"case","label":"Brown v. Plata","cite":"563 U.S. 493","y":2011,"id":"2010/09-1233","sc":1,"sum":"The Court held that a court order requiring California to reduce its prison population to remedy unconstitutional conditions in its correctional facilities did not violate the Prison Litigation Reform Act.","sumSrc":"Oyez","by":{"0":"39","1":"17"}},{"t":"case","label":"Bucklew v. Precythe","cite":"139 S. Ct. 1112","y":2019,"id":"2018/17-8151","sc":1,"op":12,"ar":9,"sum":"Baze v. Rees, 553 U. S. 35, and Glossip v. Gross, 576 U. S. ___, govern all Eighth Amendment challenges alleging that a method of execution inflicts unconstitutionally cruel pain; petitioner’s as-applied challenge to Missouri’s single-drug execution protocol—that it would cause him severe pain because of his particular medical condition—fails to satisfy the Baze-Glossip test.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"passim","1":"13, 15, 21, 25, 26","2":"passim","3":"8, 10, 11, 12, 23"}},{"t":"case","label":"Dawson v. State","cite":"554 S.E.2d 137","y":2001,"court":"Ga.","url":"https://www.courtlistener.com/c/S.E.2d/554/137/","by":{"0":"12, 13"}},{"t":"case","label":"Department of Homeland Security v. Thuraissigiam","cite":"140 S. Ct. 1959","y":2020,"id":"2019/19-161","sc":1,"sum":"The Court held that 8 U.S.C. § 1252(e)(2) as applied to the respondent Thuraissigiam does not violate the Suspension Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Ford v. Wainwright","cite":"477 U.S. 399","y":1986,"id":"1985/85-5542","sc":1,"sum":"Justice Thurgood Marshall writing for the five-justice majority noted that English common law found executing the insane \"savage and inhumane.\" In addition, no State permitted such executions. Opponents of such executions maintained that it \"offends humanity\" and that such executions had neither a deterrent nor a retributive effect.","sumSrc":"Oyez","by":{"0":"17","1":"14","2":"passim"}},{"t":"case","label":"Garcia v. Quarterman","cite":"573 F.3d 214","y":2009,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/573/214/","by":{"0":"43"}},{"t":"case","label":"Glossip v. Gross","cite":"576 U.S. 863","y":2015,"id":"2014/14-7955","sc":1,"op":2,"sum":"The Court held that the use of midazolam as the initial drug in a state’s execution protocol does not violate the Eighth Amendment’s prohibition against cruel and unusual punishment.","sumSrc":"Oyez","by":{"0":"passim","1":"13, 19, 26, 27","3":"5"}},{"t":"case","label":"Harris v. Quinn","cite":"573 U.S. 616","y":2015,"id":"2013/11-681","sc":1,"sum":"The Court held that the First Amendment prohibits the collection of union dues from home health care providers who do not wish to join a union.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Heck v. Humphrey","cite":"512 U.S. 477","y":1994,"id":"1993/93-6188","sc":1,"op":2,"ar":2,"sum":"The Supreme Court held that a defendant cannot claim damages for an allegedly unconstitutional conviction or imprisonment without showing that the conviction or sentence has been overturned in some way. The defendant must also exhaust state court remedies before bringing a §1983 action.","sumSrc":"Oyez","by":{"0":"8, 9, 11, 30, 31, 37","1":"12","2":"passim"}},{"t":"case","label":"Johnson v. Wynder","cite":"408 F. App’x 616","y":2010,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/408/616/","by":{"0":"43"}},{"t":"case","label":"Magwood v. Patterson","cite":"561 U.S. 320","y":2010,"id":"2009/09-158","sc":1,"sum":"The Court held that, when a habeas corpus application alleges new judgment for the first time, it is not \"second or successive\" under the Antiterrorism and Effective Death Penalty Act and is therefore constitutional.","sumSrc":"Oyez","by":{"0":"45, 46","2":"passim","3":"19, 20"}},{"t":"case","label":"McCleskey v. Zant","cite":"499 U.S. 467","y":1991,"id":"1990/89-7024","sc":1,"sum":"McCleskey's failure to raise his Massiah claim in his first federal habeas petition constituted abuse of the writ.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44","1":"28","2":"43"}},{"t":"case","label":"Mitchum v. Foster","cite":"407 U.S. 225","y":1972,"id":"1971/70-27","sc":1,"sum":"Title 42 U. S. C.'§ 1983, which authorizes a suit in-equity to redress the deprivation under color of state law \"of any rights, privileges, or immunities secured by theConstitution.. '.,\" is within that exception of the federal anti-injunction statute, 28 U. S. C. § 2283, that provides 'that a federal court may not enjoin state court proceedings \"except as. expressly authorized by Act of Congress.\" And in this § …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"Muhammad v. Close","cite":"540 U.S. 749","y":2004,"id":"2003/02-9065","sc":1,"sum":"In a unanimous per curiam opinion, the Court ruled that prisoners - whose suits do not question their sentences - do not need to successfully challenge those sentences before challenging prison disciplinary proceedings. The Court rejected the argument that Heck necessarily requires successful sentence appeals before any challenges can be made to prison disciplinary proceedings.","sumSrc":"Oyez","by":{"0":"27","1":"10","2":"34"}},{"t":"case","label":"Nance v. Warden, Georgia Diagnostic Prison","cite":"922 F.3d 1298","y":2019,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/922/1298/","by":{"0":"13","2":"8"}},{"t":"case","label":"Nelson v. Campbell","cite":"541 U.S. 637","y":2004,"id":"2003/03-6821","sc":1,"op":11,"sum":"The Court ruled unanimously that Nelson's suit dealt only with the proposed method of execution, not with his conviction or sentence, and was therefore different from a habeas corpus appeal. Nelson had a right to challenge the necessity of the procedure for his execution using the same legal approach he would have used to challenge the conditions of his prison.","sumSrc":"Oyez","by":{"0":"8, 15, 24, 30, 37","1":"passim","2":"12, 14, 15, 26, 34","3":"8"}},{"t":"case","label":"Panetti v. Quarterman","cite":"551 U.S. 930","y":2007,"id":"2006/06-6407","sc":1,"ar":4,"sum":"The Court held that the Fifth Circuit's analysis was too restrictive under Ford v. Wainwright , because it treated Panetti's mental condition as irrelevant as long as he had in some sense a factual awareness of the state's rationale.","sumSrc":"Oyez","by":{"0":"17, 22, 41, 42, 43, 44, 45","1":"14","2":"passim","3":"19"}},{"t":"case","label":"Skinner v. Switzer","cite":"562 U.S. 521","y":2011,"id":"2010/09-9000","sc":1,"sum":"The Court held that a convicted prisoner seeking access to biological evidence for DNA testing may assert that claim in a civil rights action under 42 U.S.C. § 1983.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"United States v. Buenrostro","cite":"638 F.3d 720","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/638/720/","by":{"0":"43"}},{"t":"case","label":"United States v. Obeid","cite":"707 F.3d 898","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/707/898/","by":{"0":"43"}},{"t":"case","label":"Wilkinson v. Dotson","cite":"544 U.S. 74","y":2005,"id":"2004/03-287","sc":1,"op":3,"sum":"Yes and No. In an 8-1 decision, the Court affirmed the appellate court and ruled that prisoners could use Section 1983 to challenge a state's parole procedures.","sumSrc":"Oyez","by":{"0":"19, 24, 25, 26, 28, 30","1":"11, 12","2":"passim","3":"5, 13, 14"}},{"t":"case","label":"Wolff v. McDonnell","cite":"418 U.S. 539","y":1974,"id":"1973/73-679","sc":1,"sum":"The Supreme Court held that while prisoners are not entitled to full due process protections, disciplinary proceedings must include written notice to the defendant of the charges, a written statement of evidence, and the opportunity for an inmate to call witnesses and present evidence.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"const","label":"Amendment VIII","clauses":[["eighth-amendment","Eighth Amendment"]],"text":"Excessive bail shall not be required, nor excessive fines imposed, nor cruel and unusual punishments inflicted.","by":{"0":"1","1":"21","2":"6, 7, 13, 27, 32"}},{"t":"usc","label":"28 U.S.C. § 2244","url":"https://www.law.cornell.edu/uscode/text/28/2244","subs":["(b)","(b)(2)","(b)(3)(A)"],"stext":{"head":"§2244. Finality of determination","paras":[[0,"(a) No circuit or district judge shall be required to entertain an application for a writ of habeas corpus to inquire into the detention of a person pursuant to a judgment of a court of the United States if it appears that the legality of such detention has been determined by a judge or court of the United States on a prior application for a writ of habeas corpus, except as provided in section 2255."],[0,"(b)(1) A claim presented in a second or successive habeas corpus application under section 2254 that was presented in a prior application shall be dismissed."],[0,"(2) A claim presented in a second or successive habeas corpus application under section 2254 that was not presented in a prior application shall be dismissed unless—"],[1,"(A) the applicant shows that the claim relies on a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable; or"],[1,"(B)(i) the factual predicate for the claim could not have been discovered previously through the exercise of due diligence; and"],[1,"(ii) the facts underlying the claim, if proven and viewed in light of the evidence as a whole, would be sufficient to establish by clear and convincing evidence that, but for constitutional error, no reasonable factfinder would have found the applicant guilty of the underlying offense."],[0,"(3)(A) Before a second or successive application permitted by this section is filed in the district court, the applicant shall move in the appropriate court of appeals for an order authorizing the district court to consider the application."],[0,"(B) A motion in the court of appeals for an order authorizing the district court to consider a second or successive application shall be determined by a three-judge panel of the court of appeals."],[0,"(C) The court of appeals may authorize the filing of a second or successive application only if it determines that the application makes a prima facie showing that the application satisfies the requirements of this subsection."],[0,"(D) The court of appeals shall grant or deny the authorization to file a second or successive application not later than 30 days after the filing of the motion."],[0,"(E) The grant or denial of an authorization by a court of appeals to file a second or successive application shall not be appealable and shall not be the subject of a petition for rehearing or for a writ of certiorari."],[0,"(4) A district court shall dismiss any claim presented in a second or successive application that the court of appeals has authorized to be filed unless the applicant shows that the claim satisfies the requirements of this section."],[0,"(c) In a habeas corpus proceeding brought in behalf of a person in custody pursuant to the judgment of a State court, a prior judgment of the Supreme Court of the United States on an appeal or review by a writ of certiorari at the instance of the prisoner of the decision of such State court, shall be conclusive as to all issues of fact or law with respect to an asserted denial of a Federal right which constitutes ground for discharge in a habeas corpus proceeding, actually adjudicated by the Supreme Court therein, unless the applicant for the writ of habeas corpus shall plead and the court shall find the existence of a material and controlling fact which did not appear in the record of the proceeding in the Supreme Court and the court shall further find that the applicant for the writ of habeas corpus could not have caused such fact to appear in such record by the exercise of reasonable diligence."],[0,"(d)(1) A 1-year period of limitation shall apply to an application for a writ of habeas corpus by a person in custody pursuant to the judgment of a State court. The limitation period shall run from the latest of—"],[1,"(A) the date on which the judgment became final by the conclusion of direct review or the expiration of the time for seeking such review;"],[1,"(B) the date on which the impediment to filing an application created by State action in violation of the Constitution or laws of the United States is removed, if the applicant was prevented from filing by such State action;"],[1,"(C) the date on which the constitutional right asserted was initially recognized by the Supreme Court, if the right has been newly recognized by the Supreme Court and made retroactively applicable to cases on collateral review; or"],[1,"(D) the date on which the factual predicate of the claim or claims presented could have been discovered through the exercise of due diligence."],[0,"(2) The time during which a properly filed application for State post-conviction or other collateral review with respect to the pertinent judgment or claim is pending shall not be counted toward any period of limitation under this subsection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2244?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":1,"head":"§2244. Finality of determination","tname":"Judiciary and Judicial Procedure","by":{"0":"40, 34, 2","2":"passim","3":"18"}},{"t":"usc","label":"28 U.S.C. § 2254","url":"https://www.law.cornell.edu/uscode/text/28/2254","subs":["(a)"],"stext":{"head":"§2254. State custody; remedies in Federal courts","paras":[[0,"(a) The Supreme Court, a Justice thereof, a circuit judge, or a district court shall entertain an application for a writ of habeas corpus in behalf of a person in custody pursuant to the judgment of a State court only on the ground that he is in custody in violation of the Constitution or laws or treaties of the United States."],[0,"(b)(1) An application for a writ of habeas corpus on behalf of a person in custody pursuant to the judgment of a State court shall not be granted unless it appears that—"],[1,"(A) the applicant has exhausted the remedies available in the courts of the State; or"],[1,"(B)(i) there is an absence of available State corrective process; or"],[1,"(ii) circumstances exist that render such process ineffective to protect the rights of the applicant."],[0,"(2) An application for a writ of habeas corpus may be denied on the merits, notwithstanding the failure of the applicant to exhaust the remedies available in the courts of the State."],[0,"(3) A State shall not be deemed to have waived the exhaustion requirement or be estopped from reliance upon the requirement unless the State, through counsel, expressly waives the requirement."],[0,"(c) An applicant shall not be deemed to have exhausted the remedies available in the courts of the State, within the meaning of this section, if he has the right under the law of the State to raise, by any available procedure, the question presented."],[0,"(d) An application for a writ of habeas corpus on behalf of a person in custody pursuant to the judgment of a State court shall not be granted with respect to any claim that was adjudicated on the merits in State court proceedings unless the adjudication of the claim—"],[1,"(1) resulted in a decision that was contrary to, or involved an unreasonable application of, clearly established Federal law, as determined by the Supreme Court of the United States; or"],[1,"(2) resulted in a decision that was based on an unreasonable determination of the facts in light of the evidence presented in the State court proceeding."],[0,"(e)(1) In a proceeding instituted by an application for a writ of habeas corpus by a person in custody pursuant to the judgment of a State court, a determination of a factual issue made by a State court shall be presumed to be correct. The applicant shall have the burden of rebutting the presumption of correctness by clear and convincing evidence."],[0,"(2) If the applicant has failed to develop the factual basis of a claim in State court proceedings, the court shall not hold an evidentiary hearing on the claim unless the applicant shows that—"],[1,"(A) the claim relies on—"],[2,"(i) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable; or"],[2,"(ii) a factual predicate that could not have been previously discovered through the exercise of due diligence; and"],[1,"(B) the facts underlying the claim would be sufficient to establish by clear and convincing evidence that but for constitutional error, no reasonable factfinder would have found the applicant guilty of the underlying offense."],[0,"(f) If the applicant challenges the sufficiency of the evidence adduced in such State court proceeding to support the State court's determination of a factual issue made therein, the applicant, if able, shall produce that part of the record pertinent to a determination of the sufficiency of the evidence to support such determination. If the applicant, because of indigency or other reason is unable to produce such part of the record, then the State shall produce such part of the record and the Federal court shall direct the State to do so by order directed to an appropriate State official. If the State cannot provide such pertinent part of the record, then the court shall determine under the existing facts and circumstances what weight shall be given to the State court's factual determination."],[0,"(g) A copy of the official records of the State court, duly certified by the clerk of such court to be a true and correct copy of a finding, judicial opinion, or other reliable written indicia showing such a factual determination by the State court shall be admissible in the Federal court proceeding."],[0,"(h) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel for an applicant who is or becomes financially unable to afford counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(i) The ineffectiveness or incompetence of counsel during Federal or State collateral post-conviction proceedings shall not be a ground for relief in a proceeding arising under section 2254."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2254?type=usc&year=mostrecent&link-type=html"},"head":"§2254. State custody; remedies in Federal courts","tname":"Judiciary and Judicial Procedure","by":{"0":"1","1":"3, 11","2":"passim"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"op":41,"ar":11,"head":"§1983. Civil action for deprivation of rights","tname":"The Public Health and Welfare","by":{"0":"passim","1":"passim","2":"passim"}},{"t":"case","label":"Allee v. Medrano","cite":"416 U.S. 802","y":1974,"id":"1973/72-1125","sc":1,"sum":"Appellee union and t he individual appellees, who atteitipted from June 1966 to June 1967 to unionize farmworkers and persuade them to support or join a strike, were subjected to persistent harassment and violence by appellants and other law enforcement officers. In July 1967 a state court issued a temporary injunction against appellees, proscribing picketing on or near property of one of the major employers in the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Americans for Prosperity Found. v. Bonta","cite":"141 S. Ct. 2373","y":2021,"id":"2020/19-251","sc":1,"ar":1,"sum":"The Ninth Circuit’s judgment, which vacated the District Court’s injunction of California’s compelled disclosure of Schedule Bs as not narrowly tailored to the State’s interest in investigating charitable misconduct, is reversed, and the cases are remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"16"}},{"t":"case","label":"Arizona Free Enter. Club’s Freedom Club PAC v. Bennett","cite":"564 U.S. 721","y":2011,"id":"2010/10-238","sc":1,"op":1,"sum":"The Court held that the Arizona campaign finance law linking public financing for candidates to the amount spent by their opponents violated the First Amendment's protection of political speech.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Arthur v. Dunn","cite":"137 S. Ct. 14","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./137/14/","sc":1,"op":1,"by":{"1":"26"}},{"t":"case","label":"(III) Cases—Continued: Burton v. Stewart","cite":"549 U.S. 147","y":2007,"id":"2006/05-9222","sc":1,"sum":"In a 9-0 per curiam opinion, the Court ruled that Burton's habeas petition should be dismissed for lack of jurisdiction. Burton had earlier filed a habeas petition challenging his conviction. Four years later, when he filed the habeas petition challenging only his sentence, Burton neglected to obtain the court authorization necessary for a \"second or successive\" petition.","sumSrc":"Oyez","by":{"1":"5","2":"13, 45, 46, 47","3":"21"}},{"t":"case","label":"Cedar Point Nursery v. Hassid","cite":"141 S. Ct. 2063","y":2021,"id":"2020/20-107","sc":1,"op":1,"sum":"A California regulation granting labor organizations a “right to take access” to an agricultural employer’s property to solicit support for unionization constitutes a per se physical taking.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"16"}},{"t":"case","label":"City of Houston v. Hill","cite":"482 U.S. 451","y":1987,"id":"1986/86-243","sc":1,"sum":"Upon shouting at police in an attempt to divert their attention from his friend during a confrontation, appellee was arrested for \"wilfully... interrupt[ing] a city policeman... by verbal challenge during an investigation\" in violation of a municipal ordinance making it unlawful for any person \"to assault, strike or in any manner oppose, molest, abuse or interrupt any policeman in the execution of his duty.\" After …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"Dunn v. Madison","cite":"138 S. Ct. 9","y":2017,"id":"2017/17-193","sc":1,"sum":"The Court determined that the Alabama court’s determination that Madison was competent to be executed was not objectively unreasonable.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"Estelle v. Gamble","cite":"429 U.S. 97","y":1976,"id":"1976/75-929","sc":1,"sum":"The Court held that the prison’s treatment of Gamble did not constitute cruel and unusual punishment under the Eighth Amendment.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Hill v. McDonough","cite":"547 U.S. 573","y":2006,"id":"2005/05-8794","sc":1,"op":10,"ar":1,"sum":"The Supreme Court held that challenging the form of execution was fundamentally different from challenging the lawfulness of a conviction or sentence, the traditional purposes of a habeas corpus appeal.","sumSrc":"Oyez","by":{"1":"passim","2":"11, 18, 24, 26","3":"7"}},{"t":"case","label":"Hope v. Pelzer","cite":"536 U.S. 730","y":2002,"id":"2001/01-309","sc":1,"sum":"The Court held that the defense of qualified immunity was precluded at the summary judgment phase of Hope's trial.","sumSrc":"Oyez","by":{"1":"11"}},{"t":"case","label":"Janus v. American Fed’n of State, Cnty., & Mun. Emps.","cite":"138 S. Ct. 2448","y":2018,"id":"2017/16-1466","sc":1,"sum":"The Court decided the State of Illinois’ extraction of agency fees from nonconsenting public-sector employees violates the First Amendment; Abood v. Detroit Bd. of Ed., 431 U.S. 209 (1977), which held otherwise, was overruled.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Johnson v. California","cite":"543 U.S. 499","y":2005,"id":"2004/03-636","sc":1,"ar":2,"sum":"The Court held that prison racial-segregation policies are subject to strict scrutiny. The Court rejected the claim that because the policy was \"neutral\" - because all prisoners were \"equally\" segregated - the policy was not subject to strict scrutiny. Racial classifications must receive strict scrutiny even when they may be said to affect the races equally.","sumSrc":"Oyez","by":{"1":"17","3":"14"}},{"t":"case","label":"Kolender v. Lawson","cite":"461 U.S. 352","y":1983,"id":"1982/81-1320","sc":1,"op":1,"sum":"The law was unconstitutionally vague because it gave excessive discretion to the police (in the absence of probable cause for an arrest) whether to stop and interrogate a suspect or leave him alone. The majority hinted that the California statute compromised the constitutional right to freedom of movement.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Malloy v. South Carolina","cite":"237 U.S. 180","y":1915,"id":"scdb/1914-074","sc":1,"ar":6,"sum":"The constitutional inhibition on ex post facto laws was intended to secure substantial personal rights against arbitrary and oppressive legislative aetiori and not to obstruct mere alterations in conditions deemed necessary for the orderly infliction of humane punishment. Rooney v. North Dakota, 196 U. S. 319.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"19","3":"5"}},{"t":"case","label":"McGehee v. Hutchinson: 854 F.3d 488 (8th Cir.), cert. denied","cite":"137 S. Ct. 1275","y":2017,"url":"https://www.courtlistener.com/c/S.%20Ct./137/1275/","sc":1,"by":{"1":"26"}},{"t":"case","label":"Monroe v. Pape","cite":"365 U.S. 167","y":1961,"id":"1960/39","sc":1,"op":1,"sum":"Yes and No. Justice William O. Douglas, writing for the majority, stated that the city police officers, in conducting an unreasonable search and seizure, had committed an action which was under the color of law, and that the police could be held liable individually under the Civil Rights Act. However, the majority further held that a municipality could not be liable under the Civil Rights Act.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Preiser v. Rodriguez","cite":"411 U.S. 475","y":1973,"id":"1972/71-1369","sc":1,"op":2,"ar":3,"sum":"When a state prisoner challenges the fact or duration of his physical imprisonment and by way of relief seeks a determination that he is entitled to immediate release or a speedier release, his sole federal remedy is a writ of habeas corpus.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"11, 15","2":"passim"}},{"t":"case","label":"Sims v. Kernan","cite":"241 Cal. Rptr. 3d 300","y":2018,"court":"Cal. Ct. App.","url":"https://www.courtlistener.com/c/Cal.%20Rptr.%203d/241/300/","by":{"1":"20"}},{"t":"case","label":"Taylor v. Riojas","cite":"141 S. Ct. 52","y":2020,"url":"https://www.courtlistener.com/c/S.%20Ct./141/52/","sc":1,"by":{"1":"11"}},{"t":"case","label":"Tennessee v. Garner","cite":"471 U.S. 1","y":1985,"id":"1984/83-1035","sc":1,"sum":"The Court ruled that a statute authorizing use of deadly force to prevent the escape of a fleeing suspected felon violates the Fourth Amendment.","sumSrc":"Oyez","by":{"1":"16, 17","2":"16"}},{"t":"case","label":"Washington State Grange v. Washington State Republican Party","cite":"552 U.S. 442","y":2008,"id":"2007/06-713","sc":1,"sum":"The Court reversed the Ninth Circuit's ruling and held the party affiliation provision constitutional. Writing for the majority, Justice Clarence Thomas explained that the state law never referred to the candidates as nominees of any particular party.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Woo Dak San v. State","cite":"7 P.2d 940","y":1931,"court":"N.M.","url":"https://www.courtlistener.com/c/P.2d/7/940/","sum":"Holding that a state legislative change in the method of execution “convert[ed] unexecuted judgments of death to be executed by hanging into judgments of death to be executed by electrocution”.","sumSrc":"brief:1","by":{"1":"19","2":"29"}},{"t":"case","label":"Zinermon v. Burch","cite":"494 U.S. 113","y":1990,"id":"1989/87-1965","sc":1,"op":1,"sum":"Burch's complaint was sufficient to state a claim under § 1983 for violation of his procedural due process rights. While Parrattand Hudson apply to deprivations of liberty, they do not preclude Burch's claim, because predeprivation procedural safeguards might have been of value in preventing the alleged deprivation of Burch's liberty without either valid consent or an involuntary placement hearing. Such a …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","by":{"1":"2"}},{"t":"usc","label":"5 U.S.C. § 704","url":"https://www.law.cornell.edu/uscode/text/5/704","by":{"1":"2"}},{"t":"law","label":"Pub. L. No. 104-134","url":"https://www.govinfo.gov/link/plaw/104/public/134","by":{"1":"17"}},{"t":"usc","label":"18 U.S.C. § 3626","url":"https://www.law.cornell.edu/uscode/text/18/3626","subs":["(a)(1)","(a)(1)(B)"],"by":{"1":"26, 24, 17"}},{"t":"usc","label":"18 U.S.C. § 3596","url":"https://www.law.cornell.edu/uscode/text/18/3596","subs":["(a)"],"by":{"1":"1"}},{"t":"usc","label":"28 U.S.C. § 2241","url":"https://www.law.cornell.edu/uscode/text/28/2241","by":{"1":"28"}},{"t":"usc","label":"28 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/28/2255","subs":["(a)","(b)","(h)","(1948)"],"stext":{"head":"§2255. Federal custody; remedies on motion attacking sentence","paras":[[0,"(a) A prisoner in custody under sentence of a court established by Act of Congress claiming the right to be released upon the ground that the sentence was imposed in violation of the Constitution or laws of the United States, or that the court was without jurisdiction to impose such sentence, or that the sentence was in excess of the maximum authorized by law, or is otherwise subject to collateral attack, may move the court which imposed the sentence to vacate, set aside or correct the sentence."],[0,"(b) Unless the motion and the files and records of the case conclusively show that the prisoner is entitled to no relief, the court shall cause notice thereof to be served upon the United States attorney, grant a prompt hearing thereon, determine the issues and make findings of fact and conclusions of law with respect thereto. If the court finds that the judgment was rendered without jurisdiction, or that the sentence imposed was not authorized by law or otherwise open to collateral attack, or that there has been such a denial or infringement of the constitutional rights of the prisoner as to render the judgment vulnerable to collateral attack, the court shall vacate and set the judgment aside and shall discharge the prisoner or resentence him or grant a new trial or correct the sentence as may appear appropriate."],[0,"(c) A court may entertain and determine such motion without requiring the production of the prisoner at the hearing."],[0,"(d) An appeal may be taken to the court of appeals from the order entered on the motion as from a final judgment on application for a writ of habeas corpus."],[0,"(e) An application for a writ of habeas corpus in behalf of a prisoner who is authorized to apply for relief by motion pursuant to this section, shall not be entertained if it appears that the applicant has failed to apply for relief, by motion, to the court which sentenced him, or that such court has denied him relief, unless it also appears that the remedy by motion is inadequate or ineffective to test the legality of his detention."],[0,"(f) A 1-year period of limitation shall apply to a motion under this section. The limitation period shall run from the latest of—"],[1,"(1) the date on which the judgment of conviction becomes final;"],[1,"(2) the date on which the impediment to making a motion created by governmental action in violation of the Constitution or laws of the United States is removed, if the movant was prevented from making a motion by such governmental action;"],[1,"(3) the date on which the right asserted was initially recognized by the Supreme Court, if that right has been newly recognized by the Supreme Court and made retroactively applicable to cases on collateral review; or"],[1,"(4) the date on which the facts supporting the claim or claims presented could have been discovered through the exercise of due diligence."],[0,"(g) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(h) A second or successive motion must be certified as provided in section 2244 by a panel of the appropriate court of appeals to contain—"],[1,"(1) newly discovered evidence that, if proven and viewed in light of the evidence as a whole, would be sufficient to establish by clear and convincing evidence that no reasonable factfinder would have found the movant guilty of the offense; or"],[1,"(2) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2255?type=usc&year=mostrecent&link-type=html"},"head":"§2255. Federal custody; remedies on motion attacking sentence","tname":"Judiciary and Judicial Procedure","by":{"1":"27, 28, 27, 27, 27","2":"40"}},{"t":"case","label":"Allen v. McCurry","cite":"449 U.S. 90","y":1980,"id":"1980/79-935","sc":1,"sum":"The Court of Appeals erred in holding that respondent's inability to obtain federal habeas corpus relief upon his Fourth Amendment claim renders the doctrine of collateral estoppel inapplicable to his § 1983 suit. Nothing in the language or legislative history of § 1983 discloses any congressional intent to deny binding effect to a state-court judgment or decision when the state court, acting within its proper …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"33, 50, 51"}},{"t":"case","label":"Boumediene v. Bush","cite":"553 U.S. 723","y":2008,"id":"2007/06-1195","sc":1,"sum":"The Court held that the Military Commissions Act of 2006 violated the Suspension Clause of the Constitution.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"Braden v. 30th Jud. Cir. Ct. of Ky.","cite":"410 U.S. 484","y":1973,"id":"1972/71-6516","sc":1,"sum":"Petitioner, imprisoned in Alabama, applied to the District Court for the Western District of Kentucky for a writ of federal habeas corpus to compel the Commonwealth of Kentucky to grant him a speedy trial on an indictment returned by the grand jury of respondent court regarding which Kentucky had lodged a detainer with Alabama. The District Court granted the writ, but the Court of Appeals reversed on the ground that …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"Calderon v. Thompson","cite":"523 U.S. 538","y":1998,"id":"1997/97-215","sc":1,"sum":"The Court held that although it was consistent with the Antiterrorism and Effective Death Penalty Act of 1996, the recall was a grave abuse of discretion.","sumSrc":"Oyez","by":{"2":"29, 43"}},{"t":"case","label":"Caplan v. Cameron","cite":"369 F.2d 195","y":1966,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/369/195/","by":{"2":"17"}},{"t":"case","label":"Dawson v. State","cite":"274 Ga. 327","y":2001,"url":"https://www.courtlistener.com/c/Ga./274/327/","sum":"Holding that electrocution is unconstitutional under Georgia law.","sumSrc":"brief:2","by":{"2":"28"}},{"t":"case","label":"Edwards v. Balisok","cite":"520 U.S. 641","y":1997,"id":"1996/95-1352","sc":1,"ar":2,"sum":"The Court held that Balisok's \"claim for declaratory relief and monetary damages, based on allegations of deceit and bias on the part of the decisionmaker that necessarily imply the invalidity of the punishment imposed, is not cognizable....\".","sumSrc":"Oyez","by":{"2":"16, 22, 29"}},{"t":"case","label":"Gomez v. U.S. Dist. Ct. for the N. Dist. of Cal.","cite":"503 U.S. 653","y":1992,"id":"1991/-767","sc":1,"sum":"A case in which the Court vacated the stay of execution because Harris’s decision to wait so long to raise his cruel and unusual punishment claim represented an “obvious attempt” to manipulate the judicial process.","sumSrc":"Oyez","by":{"2":"32"}},{"t":"case","label":"Gonzalez v. Crosby","cite":"545 U.S. 524","y":2005,"id":"2004/04-6432","sc":1,"sum":"In 7-2 opinion delivered by Justice Antonin Scalia, the Court held that Gonzalez's Rule 60(b) motion challenged only the district court's previous ruling on the federal statute of limitations. That motion was therefore not the equivalent of a successive habeas petition and could be ruled on by the district court without the 11th Circuit's precertification.","sumSrc":"Oyez","by":{"2":"39, 45"}},{"t":"case","label":"Harrington v. Richter","cite":"562 U.S. 86","y":2011,"id":"2010/09-587","sc":1,"op":1,"sum":"The Court held that a defense lawyer was not deficient for failing to consult blood evidence when planning strategy for trial.","sumSrc":"Oyez","by":{"2":"31"}},{"t":"case","label":"Hill v. Owens","cite":"292 Ga. 380","y":2013,"url":"https://www.courtlistener.com/c/Ga./292/380/","by":{"2":"4"}},{"t":"case","label":"Holden v. Minnesota","cite":"137 U.S. 483","y":1890,"id":"scdb/1890-057","sc":1,"sum":"Section 4 of the Minnesota statute of April 24, 1889, (Gen. Laws Minn. 1889, c. 20,) providing that, in case of sentence of death for murder in the first degree, the convict shall be kept in solitary confinement after the issue of the warrant of execution by the governor, and only certain persons allowed to visit him, is an independent provision, applicable only to offences committed after its passage, and is not ex …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"27"}},{"t":"case","label":"Humphrey v. Nance","cite":"293 Ga. 189","y":2013,"url":"https://www.courtlistener.com/c/Ga./293/189/","by":{"2":"7"}},{"t":"case","label":"Middlebrooks v. Parker","cite":"22 F.4th 621","y":2022,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/22/621/","by":{"2":"30"}},{"t":"case","label":"Murphy v. Nat’l Collegiate Athletic Ass’n","cite":"138 S. Ct. 1461","y":2018,"id":"2017/16-476","sc":1,"sum":"The Court decided that provisions of the Professional and Amateur Sports Protection Act (PASPA) that prohibit state authorization and licensing of sports gambling schemes violate the Constitution’s anticommandeering rule, and that no other PASPA provisions are severable from the provisions at issue.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Nance v. Chatman","cite":"571 U.S. 1177","y":2014,"url":"https://supreme.justia.com/cases/federal/us/571/1177/","sc":1,"by":{"2":"7"}},{"t":"case","label":"Nance v. Ford","cite":"140 S. Ct. 2520","y":2020,"url":"https://www.courtlistener.com/c/S.%20Ct./140/2520/","sc":1,"by":{"2":"8"}},{"t":"case","label":"Nance v. Georgia","cite":"549 U.S. 868","y":2006,"url":"https://supreme.justia.com/cases/federal/us/549/868/","sc":1,"by":{"2":"7"}},{"t":"case","label":"Nance v. State","cite":"272 Ga. 217","y":2000,"url":"https://www.courtlistener.com/c/Ga./272/217/","by":{"2":"5, 6"}},{"t":"case","label":"Nance v. State","cite":"280 Ga. 125","y":2005,"url":"https://www.courtlistener.com/c/Ga./280/125/","by":{"2":"7"}},{"t":"case","label":"Nance v. Warden","cite":"2017 WL 6597934","y":2017,"court":"N.D. Ga. Aug. 7","by":{"2":"passim"}},{"t":"case","label":"Neville v. Johnson","cite":"440 F.3d 221","y":2006,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/440/221/","by":{"2":"32"}},{"t":"case","label":"New York v. United States","cite":"505 U.S. 144","y":1992,"id":"1991/91-543","sc":1,"sum":"The Court upheld two of the three provisions of the Act under review, reasoning that Congress had the authority under the Commerce Clause to use financial rewards and access to disposal sites as incentives for state waste management.","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"Obergefell v. Hodges","cite":"576 U.S. 644","y":2015,"id":"2014/14-556","sc":1,"sum":"The Court held that the Fourteenth Amendment requires states to license and recognize same-sex marriage.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"Overton v. Bazzetta","cite":"539 U.S. 126","y":2003,"id":"2002/02-94","sc":1,"sum":"The Court held that the MDOC's regulations were valid. The Court reasoned that the fact that the regulations bear a rational relation to legitimate penological interests suffices to sustain them regardless of whether the prisoners have a constitutional right of association that has survived incarceration.","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"Owens v. Hill","cite":"295 Ga. 302","y":2014,"url":"https://www.courtlistener.com/c/Ga./295/302/","by":{"2":"50"}},{"t":"case","label":"Parker Drilling Mgmt. Servs., Ltd. v. Newton","cite":"139 S. Ct. 1881","y":2019,"id":"2018/18-389","sc":1,"sum":"Under the Outer Continental Shelf Lands Act, where federal law addresses the relevant issue, state law is not adopted as surrogate federal law on the Outer Continental Shelf.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"39"}},{"t":"case","label":"Peyton v. Rowe","cite":"391 U.S. 54","y":1968,"id":"1967/802","sc":1,"sum":"A prisoner serving consecutive sentences is \"in custody\" under any one of them for purposes of § 2241 (c) (3) and may in a federal habeas corpus proceeding thereunder challenge the constitutionality of a sentence scheduled for futur6 service. The decision in McNally v. Hill, supra, which was compelled neither by statute nor history and which constitutes an indefensible barrier to prompt adjudication of …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"16"}},{"t":"case","label":"Pizzuto v. Tewalt","cite":"997 F.3d 893","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/997/893/","by":{"2":"32","3":"20"}},{"t":"case","label":"Ramirez v. Collier","cite":"595 U.S. ___","y":2022,"court":"Mar. 24","id":"2021/21-5592","sc":1,"op":2,"sum":"Petitioner Ramirez is likely to succeed on his claims under the Religious Land Use and Institutionalized Persons Act of 2000 because Texas’s restrictions on religious touch and audible prayer in the execution chamber burden religious exercise and are not the least restrictive means of furthering the State’s compelling interests.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"14, 18","3":"1"}},{"t":"case","label":"Rhines v. Weber","cite":"544 U.S. 269","y":2005,"id":"2004/03-9046","sc":1,"op":1,"sum":"The Court held that a district court could stay a mixed petition to allow a petitioner to present unexhausted claims in state court and then return to federal court.","sumSrc":"Oyez","by":{"2":"passim"}},{"t":"case","label":"Rose v. Lundy","cite":"455 U.S. 509","y":1982,"id":"1981/80-846","sc":1,"sum":"The judgment is reversed and the case is remanded. 624 F. 2d 1100, reversed and remanded. JUSTICE O'CONNOR delivered the opinion of the Court with respect to Parts I, II, III-A, III-B, and IV, concluding that a district court must dismiss habeas petitions containing both unexhausted and exhausted claims. A rule requiring exhaustion of all claims in state courts promotes comity and furthers the purposes underlying …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"41, 42"}},{"t":"case","label":"Sale v. Haitian Centers Council, Inc.","cite":"509 U.S. 155","y":1993,"id":"1992/92-344","sc":1,"sum":"And, it found that both section 243(h) and Article 33 are silent regarding extraterritorial application. In fact, the language of both suggests that only individuals who have already arrived on United States soil are protected, and their use throughout history confirms this interpretation. Thus, the judgment of the Court of Appeals is reversed.","sumSrc":"Oyez","by":{"2":"42"}},{"t":"case","label":"Sanders v. United States","cite":"373 U.S. 1","y":1963,"id":"1962/202","sc":1,"sum":"The Court should have granted a hearing on the second motion.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"40, 41"}},{"t":"case","label":"Slack v. McDaniel","cite":"529 U.S. 473","y":2000,"id":"1999/98-6322","sc":1,"sum":"The Court held that a federal habeas corpus petition filed by a state prisoner, after an initial petition was dismissed without adjudication on the merits, does not constitute a \"second or successive\" petition, subject to dismissal for abuse of writ.","sumSrc":"Oyez","by":{"2":"2, 38, 44, 45"}},{"t":"case","label":"Solid Waste Agency of N. Cook Cnty. v. U.S. Army Corps of Eng’rs","cite":"531 U.S. 159","y":2001,"id":"2000/99-1178","sc":1,"sum":"The Court held that the provision of the CWA, which requires those discharging fill material into navigable waters to obtain a permit from the Corps, does not extend to isolated, abandoned sand and gravel pits with seasonal ponds, which provide migratory bird habitats.","sumSrc":"Oyez","by":{"2":"37"}},{"t":"case","label":"State v. Ledford","cite":"2009 WL 10430994","y":2009,"court":"Ga. Super. Ct. May 22","by":{"2":"29"}},{"t":"case","label":"Stewart v. Martinez-Villareal","cite":"523 U.S. 637","y":1998,"id":"1997/97-300","sc":1,"sum":"Announced by Chief Justice William H. Rehnquist, the Court ruled Martinez-Villareal cannot be barred from raising his incompetency claim in a successive petition because his claim was really amended.","sumSrc":"Oyez","by":{"2":"47"}},{"t":"case","label":"Tompkins v. Sec’y, Dep’t of Corr.","cite":"557 F.3d 1257","y":2009,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/557/1257/","sum":"Noting that South Carolina adopted its challenged protocol eleven years after the prisoner had filed his first habeas petition.","sumSrc":"brief:3","by":{"2":"32","3":"20"}},{"t":"case","label":"United States v. Mauro","cite":"436 U.S. 340","y":1978,"id":"1977/76-1596","sc":1,"sum":"After respondents in No. 76-1596, who at the time were serving state sentences in New York, were indicted on federal charges in the United States District Court for the Eastern District of New York, that court issued writs of habeas corpus ad prosequendum directing the state prison wardens to produce respondents in court. Subsequently, following their arraignments, respondents were retained in federal custody in New …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"17"}},{"t":"case","label":"United States v. Windsor","cite":"570 U.S. 744","y":2013,"id":"2012/12-307","sc":1,"sum":"The Court found that the Defense of Marriage Act (DOMA) was unconstitutional under the equal protection clause of the Fifth Amendment.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"Weaver v. Graham","cite":"450 U.S. 24","y":1981,"id":"1980/79-5780","sc":1,"sum":"Held.: A Florida statute repealing an earlier statute and reducing the amount of \"gain time\" for good conduct and obedience to prison rules deducted from a convicted prisoner's sentence is unconstitutional as an ex post facto law as applied to petitioner, whose crime was committed before the statute's enactment.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"25"}},{"t":"case","label":"Wilkerson v. Utah","cite":"99 U.S. 130","y":1878,"id":"scdb/1878-134","sc":1,"by":{"2":"27"}},{"t":"case","label":"Woodford v. Garceau","cite":"538 U.S. 202","y":2003,"id":"2002/01-1862","sc":1,"sum":"The Court held, for purposes of Lindh, that a case does not become \"pending\" until an actual application for habeas corpus relief is filed in federal court.","sumSrc":"Oyez","by":{"2":"2, 29, 43"}},{"t":"usc","label":"28 U.S.C. § 2242","url":"https://www.law.cornell.edu/uscode/text/28/2242","by":{"2":"22"}},{"t":"usc","label":"28 U.S.C. § 2243","url":"https://www.law.cornell.edu/uscode/text/28/2243","by":{"2":"22"}},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"2":"passim"}},{"t":"rule","label":"Fed. R. Civ. P. 59","url":"https://www.law.cornell.edu/rules/frcp/rule_59","subs":["(e)"],"by":{"2":"38, 42"}},{"t":"case","label":"Hill v. Owens","cite":"738 S.E.2d 56","y":2013,"court":"Ga.","url":"https://www.courtlistener.com/c/S.E.2d/738/56/","by":{"3":"16"}},{"t":"case","label":"Moeller v. Weber","cite":"523 F. Supp. 2d 975","y":2007,"court":"D.S.D.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/523/975/","by":{"3":"11"}},{"t":"case","label":"In re Ohio Execution Protocol (Fears v. Morgan)","cite":"860 F.3d 881","y":2017,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/860/881/","by":{"3":"9"}},{"t":"case","label":"Owens v. Hill","cite":"758 S.E.2d 794","y":2014,"court":"Ga.","url":"https://www.courtlistener.com/c/S.E.2d/758/794/","by":{"3":"23"}},{"t":"case","label":"Rumsfeld v. Padilla","cite":"542 U.S. 426","y":2004,"id":"2003/03-1027","sc":1,"sum":"Instead, in 5-to-4 opinion written by Chief Justice William H. Rehnquist, the Court found that the case had been improperly filed. Under federal law, a petition for a writ of habeas corpus can only be filed against the person directly responsible for a prisoner's confinement or, put another way, the person with the power to bring the prisoner to court.","sumSrc":"Oyez","by":{"3":"13"}},{"t":"case","label":"iii Thompson v. Clark","cite":"142 S. Ct. 1332","y":2022,"id":"2021/20-659","sc":1,"sum":"Petitioner Thompson’s showing that his criminal prosecution ended without a conviction satisfies the requirement to demonstrate a favorable termination of a criminal prosecution in a Fourth Amendment claim under 42 U. S. C. §1983 for malicious prosecution; an affirmative indication of innocence is not needed.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"10"}},{"t":"case","label":"Wilkinson v. Austin","cite":"545 U.S. 209","y":2005,"id":"2004/04-495","sc":1,"sum":"The Court held that the procedures by which the New Policy classified prisoners for placement at the facility provided sufficient protection to comply with the due process clause. The Court reasoned that procedural protections afforded to prisoners were necessarily limited, and that the New Policy sufficiently minimized risk of erroneous placement.","sumSrc":"Oyez","by":{"3":"14"}},{"t":"case","label":"OTHER AUTHORITIES Brief of State Appellees, In re Ohio Execution Protocol Litigation (Adams v. DeWine)","cite":"946 F.3d 287","y":2019,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/946/287/","by":{"3":"9"}}]};